import { test, expect } from '@playwright/test';

test.describe('Accessibility - Reading Order', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should match the visual order of elements', async ({ page }) => {
    const heading = await page.getByRole('heading', { name: 'Page Title' });
    const paragraph = await page.getByText('This is a sample paragraph.');
    const button = await page.getByRole('button', { name: 'Submit' });

    const readingOrder = [heading, paragraph, button];
    const visualOrder = await Promise.all(readingOrder.map(async (element) => {
      return await element.evaluate(el => el.getBoundingClientRect().top);
    }));

    const sortedVisualOrder = [...visualOrder].sort((a, b) => a - b);
    expect(visualOrder).toEqual(sortedVisualOrder);
  });

  test('should have elements in correct reading order', async ({ page }) => {
    const elements = [
      await page.getByRole('heading', { name: 'Page Title' }),
      await page.getByText('This is a sample paragraph.'),
      await page.getByRole('button', { name: 'Submit' })
    ];

    const readingOrder = await Promise.all(elements.map(async (element) => {
      return await element.evaluate(el => el.textContent);
    }));

    const expectedOrder = ['Page Title', 'This is a sample paragraph.', 'Submit'];
    expect(readingOrder).toEqual(expectedOrder);
  });
});
